function renderFigures(figures) {
  const container = document.getElementById("figures");

  for (const figure of figures) {
    const link = document.createElement("a");
    link.className = "figure-card";
    link.href = figure.href;
    link.target = "_blank";
    link.rel = "noopener noreferrer";

    const image = document.createElement("img");
    image.src = figure.src;
    image.alt = "";
    image.loading = "lazy";

    const title = document.createElement("strong");
    title.textContent = figure.caption || figure.href;

    const detail = document.createElement("small");
    detail.textContent = figure.detail;

    const description = document.createElement("p");
    description.textContent = figure.description;

    link.append(image, title, detail, description);
    container.append(link);
  }
}

renderFigures(figures);
